<script setup lang="ts">
import { ref, computed } from 'vue'

export interface VersionNode {
  id: string
  version_no: string
  label?: string
  word_count: number
  created_at: string
  is_current: boolean
  is_favorite: boolean
  summary?: string
  rating?: number
  template_used?: string
  generation_time_ms?: number
  agent_used?: string
  diff_prev?: string
  highlights?: string[]
}

const props = defineProps<{
  versions: VersionNode[]
  currentVersionId?: string
}>()

const emit = defineEmits<{
  (e: 'select', versionId: string): void
  (e: 'compare', versionId: string): void
}>()

const expandedId = ref<string | null>(null)

const expandedVersion = computed(() =>
  expandedId.value ? props.versions.find(v => v.id === expandedId.value) : null
)

function toggleExpand(versionId: string) {
  if (expandedId.value === versionId) {
    expandedId.value = null
  } else {
    expandedId.value = versionId
  }
}

function handleVersionClick(version: VersionNode) {
  toggleExpand(version.id)
}

function formatDate(dateStr: string): string {
  const d = new Date(dateStr)
  const now = new Date()
  const diffMs = now.getTime() - d.getTime()
  const diffMins = Math.floor(diffMs / 60000)
  if (diffMins < 1) return '刚刚'
  if (diffMins < 60) return `${diffMins} 分钟前`
  const diffHours = Math.floor(diffMins / 60)
  if (diffHours < 24) return `${diffHours} 小时前`
  return `${d.getMonth() + 1}/${d.getDate()} ${d.getHours()}:${d.getMinutes().toString().padStart(2, '0')}`
}

function formatFullDate(dateStr: string): string {
  const d = new Date(dateStr)
  return `${d.getFullYear()}-${(d.getMonth()+1).toString().padStart(2,'0')}-${d.getDate().toString().padStart(2,'0')} ${d.getHours()}:${d.getMinutes().toString().padStart(2,'0')}`
}

function formatDuration(ms?: number): string {
  if (!ms) return '—'
  const s = Math.floor(ms / 1000)
  if (s < 60) return `${s} 秒`
  const m = Math.floor(s / 60)
  return `${m} 分 ${s % 60} 秒`
}

function formatWords(count: number): string {
  if (count >= 10000) return `${(count / 10000).toFixed(1)}万`
  if (count >= 1000) return `${(count / 1000).toFixed(1)}k`
  return count.toString()
}
</script>

