    </div>

    <!-- 时间线 -->
    <div class="timeline-track">
      <!-- 垂直连接线 -->
      <div class="timeline-line"></div>

      <!-- 版本节点 -->
      <div
        v-for="(v, idx) in versions"
        :key="v.id"
        class="version-node"
        :class="{
          'is-current': v.is_current,
          'is-favorite': v.is_favorite,
          'is-expanded': expandedId === v.id,
        }"
        @click="handleVersionClick(v)"
      >
        <!-- 节点圆点 -->
        <div class="node-dot">
          <span v-if="v.is_current" class="dot-inner"></span>
          <span v-else-if="v.is_favorite" class="dot-star">⭐</span>
        </div>

        <!-- 版本卡片 -->
        <div class="version-card">
          <div class="card-header">
