            <div class="card-header-right">
              <span v-if="v.is_current" class="version-badge current">当前</span>
              <span v-else-if="v.is_favorite" class="version-badge favorite">收藏</span>
              <span class="expand-arrow" :class="{ expanded: expandedId === v.id }">▾</span>
            </div>
          </div>

          <div v-if="v.summary" class="version-summary">{{ v.summary }}</div>

          <div class="card-footer">
            <span class="version-words">{{ formatWords(v.word_count) }} 字</span>
            <span class="version-time">{{ formatDate(v.created_at) }}</span>
          </div>

          <div v-if="v.rating" class="version-rating">
            <span v-for="i in 5" :key="i" class="star" :class="{ filled: i <= (v.rating || 0) }">★</span>
          </div>

          <!-- 展开详情 -->
          <transition name="version-detail">
            <div v-if="expandedId === v.id" class="version-detail">
              <div class="detail-grid">
                <div class="detail-item">
                  <span class="detail-item-label">生成时间</span>
                  <span class="detail-item-value">{{ formatFullDate(v.created_at) }}</span>
                </div>
                <div class="detail-item">
                  <span class="detail-item-label">生成耗时</span>
                  <span class="detail-item-value">{{ formatDuration(v.generation_time_ms) }}</span>
