                  <span class="detail-item-value">{{ v.template_used || '默认' }}</span>
                </div>
                <div class="detail-item">
                  <span class="detail-item-label">字数</span>
                  <span class="detail-item-value">{{ v.word_count.toLocaleString() }} 字</span>
                </div>
              </div>

              <div v-if="v.highlights && v.highlights.length > 0" class="detail-highlights">
                <div class="detail-highlights-title">✨ 版本亮点</div>
                <div class="highlight-tags">
                  <span v-for="(h, i) in v.highlights" :key="i" class="highlight-tag">{{ h }}</span>
                </div>
              </div>

              <div class="detail-actions">
                <button
                  v-if="!v.is_current"
                  class="detail-action-btn primary"
                  @click.stop="emit('select', v.id)"
                >
                  🔄 切换到此版本
                </button>
                <button
                  class="detail-action-btn"
                  @click.stop="emit('compare', v.id)"
                >
                  📊 对比差异
                </button>
              </div>
            </div>
          </transition>

          <div class="card-actions">
            <button
              v-if="!v.is_current"
              class="action-btn switch-btn"
              @click.stop="emit('select', v.id)"
            >
              切换到此版本
            </button>
            <button
              class="action-btn compare-btn"
              @click.stop="emit('compare', v.id)"
            >
              对比
            </button>
          </div>
        </div>
      </div>

      <!-- 空状态 -->
      <div v-if="versions.length === 0" class="timeline-empty">
        <div class="empty-illustration">
          <div class="empty-node-line">
            <span class="empty-dot"></span>
            <span class="empty-dot ghost"></span>
            <span class="empty-dot ghost"></span>
          </div>
        </div>
        <span class="empty-icon">📜</span>
        <span class="empty-text">暂无版本记录</span>
